rows["480:1010657172"]="아, 여기 계신다. 도움을 기대하라고 말씀드렸어요. 그래서 좀 더 자세히 들어보세요. 상황이 이렇습니다. 저는 아안키라지에서 임박하는 전쟁에 대비하기 위해 $2055w 보라색 낙엽을 모으는 일을 맡았습니다. 현재까지 우리는 $2054w를 가지고 있습니다.$B$B사실 들판에 가서 꽃을 모으는 것은 당신과 같은 사람들에게 달려 있습니다. 저는 여기 그들이 제대로 유지되고 있고, 실리티드와 다른 어떤 것에 대항하여 사용될 새로운 창의적인 응용을 찾기 위해 필요합니다."
rows["480:1318785079"]="피 엘프들은 어떤 이유로 우리를 막고 싶어$B$B<트레엘로스 관장님께서는 몇 초 더 정신을 차려주기 위해 노력합니다.>$B$B그들은 파손된 중 한 명을 보내서...$B$B그들은 죽었고, 그들은 모두 죽었습니다. 그들은 도망치려고 했습니다. 운이 좋은 사람들은 몰랐습니다.$B$B폭발의 가장자리에 있었을 거야 끔찍한 일이야$B$B<트레엘로스는 절망에 빠지고, 마치 당신이 없는 것처럼 바로 너로 바라보고 있다.>"
rows["480:73004465"]="저는 제 자연의 남은 삶을 지식의 추구로 돌아다니며, 제 이전 사람들보다 더 이상한, 신비로운 인종들을 만나며, 더 많은 것을 보고, 새로운 땅이 지평선 너머로 사라질 때까지 고대 칼림도어의 길과 너비를 여행했습니다.$B$B하지만... 아직은 내가 알지 못하는 일이 많았는데 마지막 여행이 다가오고 있다는 것을 느꼈고,$B$B내가 쓰러지면서, 내 삶이 끝났습니다. 그때 그들은 나를 찾았습니다."
rows["480:901805916"]="너무 아름다운 존재, 그렇지 않나요? 그의 작은 크기로 당신을 속이지 마십시오. 어린 나이에  ⁇  ⁇ 은은 치명적입니다.$b$b제가 발견하기 전에  ⁇ 초그는 그들의 지능을 거의 고려하지 않고 무기로 사용되었는데, 우리는 그들을 통제하기 위해 싸웠어요.$b$b우리는 더 이상 강제로 통제할 필요가 없는 피조물들과 관계를 맺어 대신 협력이 이루어졌습니다.$b$b코보크는 내 실험의 다음 단계였습니다."
rows["481:1728273113"]="제가 말했듯이, 우리가 보던 것은 설명에 도전하지 않았습니다.$B$B제 사람들은 어디에도 찾아볼 수 없었지만, 그들의 자리에 로봇과 안드로이드들이 있는 진정한 군대가 있었습니다.$B$B드로이드는 모두 거미처럼 생겼고 우리를 기다리고 있다고 말했어요. 사실, 그들의 이상한 방식으로, 그들은 우리를 알고 있는 것처럼 행동했습니다. 우리는 포위되었고 빠르게 펌프 스테이션의 꼭대기에 끌려갔습니다.$B$B그 곳에서 그들의 지도자를 보았고 생존한 기둥들에 대해 무엇을 했는지도 봤습니다!"
rows["481:1774285886"]="왜 강하다고 부르는지 아세요? '마지막으로 언덕 아래로 굴러오면, 상장할 수 없고, 논리할 수도 없었어요.'$B$B맥주 밸런치처럼 죽기 좋은 방법이죠$B$B언덕 밑에 있는 고아집에 떨어질 때 그 배가 폭발했고, 입이 열려서 진흙 웅덩이에 뛰어들었고,$B$B<오른  ⁇ 티 피트는 바지를 떨어뜨린다>"
rows["483:1025180679"]="며칠 동안 침묵을 지키고 나서, 전원들을 발굴해서 무대에 보냈는데, 그들은 돌아오지 않았습니다.$B$B다음날 다른 그룹을 보내서 똑같은 결과를 얻었고, 비행기를 몇 개 잃었습니다.$B$B그 때 저는 남쪽으로 도움을 구하러 사람을 보냈습니다. 그리고 우리는 최악의 상황에 대비하기 위해 몸을 숙이고 전기를 무기와 로봇을 만드는 데 바꿨습니다.$B$B며칠 전 우리가 그랬을 때, 우리는 우리의 눈을 믿을 수 없었습니다!"
rows["483:1420366425"]="황색 페이지를 가진 일기에는 마지막 항목이 열려 있습니다.$B$B\"하롤드가 돌아간 후 무슨 일이 일어날지 모르겠어요. 내가 찾을 수 있는 유일한 곳으로 끌어당기기 위해 모든 것을 내버려뒀어요.$B$B나 여기서 나가길 바래요, 하지만 돈이 필요해요 우리 물건은 모두 옷장 안에 있어요$B$B나는 그것에 휴식을 취할 것이다, 나는 이제 죽은 피곤했다. \""
rows["485:1087965374"]="우리의 가장 새로운 매력, 그리고 당신에게는 아무런 비용도 없이, 이 미니어 탱크, 또는 우리가 똑똑하게 이름 붙인 Tonks,$B$B모든 톤크는 장치들을 갖추고 있고, 적에 대한 특별한 힘을 발휘할 수 있습니다!$B$B친구들과 대전하고, 순항하거나, 아니면 혼란을 일으켜... 선택은 당신 몫이야!"
rows["485:124120517"]="다음 선택은 기다리고 있습니다.$B$B당신은 현재 당신과 전쟁 중인 잔인한 나라에 대한 당신의 의지를 위해 외교 임무에 있습니다. 전쟁은 양쪽에서 비용이 많이 들었습니다.$B$B외교식에서 상대국의 통치자가 당신의 친절한 신부에게 잔혹하게 욕을 당하는 것을 들게 되는데, 당신은 그 통치자가 당신의 귀에서 그것을 말하고자 했다는 것을 확신하지만, 그럼에도 불구하고 그는 당신의 신부 의 명예를 훼손했습니다.$B$B선택해"
rows["485:1305270420"]="오, 그 구석에서 내보내주셔서 감사합니다. 왜냐하면 저는 오래동안 그 안에 있었고, 일주일 동안 햇볕에  ⁇ 은 양고기 냄새가 나고 있었고, 저는 양고기를 좋아하지 않습니다. 왜냐하면 제가 어렸을 때, 아주 작은 때, 저는 실제로 한 분 동안 양으로 변했습니다. 그래서 저는 양이 되는 느낌은 알고 있습니다. 그리고 저는 누군가가 저를 먹으면 좋겠어요. 특히 고양이가 된 트롤이요.$b$b애슐리는 깊은 숨을 쉬고$b$b내 머리카락은 어때?\010"
rows["485:1471303020"]="'살살꾼'은 '무죄의 피'와 '크르톤오스'라는 어두운 주인에게 어떻게 그의 주인에게 진정시켜야 하는지 이야기했습니다.$B$B마침내 짐승은 그의 실험을 끝냈고, 우리는 모든 생명으로부터 지쳐졌고, 우리의 정신은 찢어졌다. 죽음의 달콤한 포옹이 우리 위에 있었고, 우리는 그것을 열리고 환영했습니다. 그러나 그의 무한한 잔인함으로, 가살꾼은 우리를 죽음의 문에서 부활시켰다.$B$B우린 살아있어야 하고 그의 맹렬한 괴물들에게 던져질 거야"
rows["485:163901235"]="이 탑에 문제가 있어 내가 아프고, 그 탑 근처에 일하는 다른 벤처 코 직원들도 아프고$B$B지난주, 두 명의 순찰자가 죽었고, 순식간에 무인 무인으로 다시 살아났습니다!$B$B생명력은 내 몸에서 빠져나가고 있어 통제력을 잃는 것 같고, 권력이 넘어가고 있어, 나쁜 권력은... "
rows["485:1747180599"]="권력의 파라곤은 고대 구루바시 제국의 유물입니다. 우리는 그들을 찾고 있습니다. 그들은 우리에게 엄청난 수집 가치를 가지고 있을 뿐만 아니라, 우리는 또한 그들이 오래된 제국의 가장 강력한 마지를 가지고 있다고 믿습니다.$B$B ⁇ 루루브에서 세 종류의 파라곤을 찾을 수 있습니다. 동전, 보석, 원시품. 우리가 찾는 양으로 가져와, 우리는 Zandalar에서 만든 가장 훌륭한 물건으로 보상을 받게 될 것입니다.$B$B믿으세요!\010"
rows["485:1800598132"]="<볼진은 3개의 손가락으로 흉터를 넘어서고 있다.>$b$b길거리가 길어졌는데, 가로쉬가 목에 칼을 들고 날 죽여버렸어요.$b$b우리는 셰도-판 수도원에 갔고, 나를 도와서 좀 심장을 찾아내야 해. 호드 그랬어요$b$b내가 결정했지 호드를 돌려받아$b$b다크스피어들은 절대 죽지 않는다."
rows["485:232062930"]="돌모아는 당신을 쳐다보고 있습니다. 마치 당신의 영혼을 들여다보고 있는 것처럼.$B$B제 딸 테라드라스는 테라모크의 크리스탈 동굴에서 깊은 곳에 숨어 사라진 사랑인 자에타르를 슬퍼하고 있었습니다.$B$B만약 내가 육체의 저주로 고통받는 존재에 신뢰할 이유가 있다면 그날 날 내게 빼앗겼고, 그럼에도 불구하고 네가 거만하고 계속 서있지$B$B언젠가는, 당신은 당신의 유용성을 넘을 것입니다."
rows["485:412890533"]="아즈갈로르 같은 동굴 주인을 죽이는 것은 작은 업적이 아닙니다. 우리가 더 많은 시간을 가졌다면, 당신과 당신의 동료들의 이야기를 듣고 싶습니다. 아치몬드는 우리에게 그 휴식을 주지 않을 것입니다. 그러나 내 스카우트는 이미 우리 캠프 밖에서 레지옹이 엄청난 힘을 축적하고 있다고 보고했습니다. 아치몬드는 세계 나무에 매우 가깝습니다. 우리는 레이디 프라우드무어의 도움으로 대피하고 있습니다. 당신은 즉시 세계 나무로 가야합니다. 우리의 세계의 운명은 여전히 결정되지 않습니다."
rows["486:1196038102"]="바슈지르의 레벨 79-81 던전인 타이드의 왕좌는 이제 초기 테스트를 위해 사용할 수 있습니다. 던전은 진행 중이며 최종 보스가 사용할 수 없습니다. 던전에 이동하기 전에 전체 그룹에 함께하십시오. 멘팅 스톤은 아직 이 던전에서 사용할 수 없습니다.\010물의 왕좌를 떠나려면, 그냥 감옥 내부의 정상적인 출구로 빠져나와 다라란으로 이동할 것입니다."
rows["486:1334785775"]="여기와 라저힐의 충돌은 맥주 흐름을 망쳤어$b$b도와주고 싶다면, 이럴게요.$b$b매번  ⁇ 을 가져오면, 몇 개의 토큰을 줄게 되는데,  ⁇ 을 더 오래 사용하게 해 줄게 되죠.$b$b하지만 일단 시작하면 내일까지 다시 할 수 없을 겁니다.$b$b이 일을 할 준비가 됐는지 확신하십니까?"
rows["486:216198965"]="샤트라스는 쓰러지지 않았으며, 오히려 시리라는 나아루가 실정문 계곡에 성공적으로 침입했습니다.$B$B그는 알도르와 스크라이어의 도움으로 일리던의 군대에 맞서 전쟁을 계속하고 있다.$B$B하지만 두 단체는 옛 적대에서 포기하지 않고 있습니다. 이 두 단체는 나아루를 도와주는 명예에 경쟁합니다. 매일,"
rows["486:233966556"]="우리는 항상 카르가트 블레이드피스트를 기억할 것입니다. 그는 한때 호드에 있었던 것 중 한 명이었습니다. 그는 지금까지 살았던 최고의 전사 중 한 명이었습니다. 얼라이언스도 이것을 인정합니다.$B$B카가스 탐험대는 그의 명예로 지명됐고, 우리는 그의 이름을 지키기로 계획하고 있습니다. 호드 그들은 마땅히 그들의 몫이 될 것입니다.$B$B타우리산에 대항해 전쟁장의 칼이 될 거야"
rows["486:605342571"]="우리 적들이 우리 코 아래에서 숨기려고 할 깊이에 대해 설명하는 것이 현명해지겠죠.$B$B우선, 우리 적은 그림자 협의회입니다. 제가 여러분에게 어떤 일을 맡겼든,$B$B회의 안에서 많은 신조들이 존재하지만 어리석은 사람들로부터 그들의 행동을 숨기기 위해서만$B$B타는 칼, 아구스 웨이크, 가려지는 칼 같은 그룹은 모두 협의회의 도구입니다."
rows["486:824811992"]="나랄렉스는 다시 잠들게!$b$b오래전 나라렉스는 이 동굴로 향했습니다. 명예로운 목표로 에메랄드 드림에 들어가서 다시 성장하기 위해서요. 불모의 땅 그는 초록색 숲으로 돌아갔고, 그의 생각이 뱀처럼 비전을 통해 오염되었습니다.$b$b이제, 유행 동물들이 그의 꿈에서 땅으로 침투하고 있어 그는 악몽에서 깨어나야 합니다. 아니면 그는 영원히 사라지고,$b$b그의 부패한 종인 Fanglords가 죽여졌을 때야 내가 깨어날 수 있는 의식을 수행할 수 있다.\010"
rows["486:964705869"]="지구인은 창조자들에 의해 만들어진 합성 종족이며, 아제로스로 지정된 세계 초기 인구에서 씨앗 종족 중 하나로 기능한다. 지구인은 창조자의 노력에 도움을 주기 위해 창조자들에 의해 창조되었다.$B$B창조자들이 심어준 다른 세계들에서 사용되는 표준 지하 존재 매트릭스의 변형이다. 이 프로토타입 인종의 건설은 초기 합성 후 관찰된 다양한 기상들을 만들어 냈습니다."
rows["487:1009491376"]="과거 에 엘드레'타라스는 마법 의 힘 을 띠고 있었으며, 그 성스러운 방 에 거주 하는 사람 들 은 엄청난 힘 을 가지고 있었다. 그러한 밤 엘프 중 한 명 은 자연 의 힘 을 자기 가 만들어 낸 강력한 유물 으로 바꾸어 놓은 자연학자 인 밀리센트 세레네 이다.$B$B피란의 열매는 그녀의 최고 성과였습니다. 그녀는 특별히 준비된 달의  ⁇ 을 사용하여 보호와 성장의 광경을 가진 이국적이고 활기찬 포도나무를 자랐습니다. 엘드레'타라스는 모두 그 존재에서 번성했습니다."
rows["487:1445360154"]="한때는 제 주인에게 원하는 것을 물어볼 수 있었지만 지금은 거의 모든 사람을 연습생으로 받아들여서$B$B난 화가 나지만 그의 명령을 의심하지 않는다. 나는 단지 웃긴 옷을 입고,$B$B이 거꾸로 돌아다니는 것도 지루해 해"
rows["487:1811960054"]="합성에서의 지구인의 유일한 이상은 높은 스트레스 환경에서 사용되는 동안 매트릭스 불안정화 경향입니다.$B$B추가: 깊은 땅 조각은 자연스럽게 새로운 매트릭스 디자인에 적합했고 따라서 고 스트레스 환경의 복제 자격을 충족시키지 못했습니다.$B$B이 불안정화는 창조자들에게 지구인의 주요 서비스 순환에 이르기까지 발견되지 않았습니다. 창조자들은 회수 및 재합성에 비해 합성 후 수정 작업을 시작했습니다."
rows["487:2034965128"]="아주 잘 됐어요$B$B당신 의 ᄀ주께서 당신 의 옥수수 들 을 독도자 들 과 도둑 들 에게서 보호 하라고 명령 하셨읍니다. 어느 날 밤 한 번 경찰을 하면서, ᄂ색색 의상 을 입은 한 ᄀ주 의 ᄂ을 발견 한 뒤, 당신 은 그 에게 대거하여 그 의 생명 을 구제 하였읍니다. 그 는 그 의 가문의 양식을 위해 옥수수를 훔치고 있다고 주장 하였읍니다. 그 땅 의 주 는 당신 의 ᄀ주 의 세금 을 너무 많이 요구 하고 있읍니다. 당신 의 ᄂ주 는 그 ᄂ땅 에 걸쳐 ᄀ혹스러운 세금 으로 알려져 있읍니다.$B$B선택해"
rows["487:2054917607"]="리치 왕의 전염병 의 비밀을 밝혀내기 위해 왕립 약학 협회 는 수년 동안 노력 해 왔으며, 마침내 이 일을 해냈습니다!$B$B역사의 이 전환점에도 불구하고 아직 발견할 일이 너무 많아요.$B$B적어도 저는 스컬지 네크로폴리에 대해 걱정할 필요가 없습니다. 얼라이언스는 그 문제를 다루고 있습니다. 이것은 전염병의 비밀을 깊이 파헤치고 내가 할 수 있는 것을 발견할 충분한 시간을 남겨줍니다."
rows["488:1885468148"]="제 인지 능력 이 향상 된 것 이 도움 이 되어, 저는 제 종족의 나머지 종족 을 새롭게 바라볼 수 있습니다. 우리 의 에너지 의 대부분 은 신선 한 먹이를 사냥 하는 데 사용 되었습니다. 왜 우리 는 우리 의 먹거리를 얻기 위해 가축적 인 생물 의 저장소를 개발 하는 데 그 시간 을 투자 하지 않았습니까?$B$B저는 인간들이 훌륭한 먹거리를 만들 수 있다고 생각하기 쉽죠. 그들은 빨리 번식하고, 잘 살을 찌르고, 수확 시간까지 양떼를 위한 소박한 일을 할 수 있도록 훈련받을 수 있습니다."
rows["488:2140990453"]="어서 오세요. 다크문 축제에 오신 것을 환영합니다! 주저하지 말고 마음껏 즐기세요. 겁나 먼 나라에서 온 이국적인 유물을 사고 싶다면 라흐라를 찾아가세요. 혹시 운 좋게도 다크문 축제 카드가 있다면 학자 타데우스 팔레오와 얘기해 보세요. 배가 고프다고요? 목이 마르신가요? 운이 참 좋으신 분이군요! 바로 여기 실라니아와 스탬프가 맛있는 음식과 음료를 팔고 있거든요. 특히 매콤한 핫윙을 좀 드신 후에 입가심으로 다크문 폭탄주를 마시면 아주 딱이에요. 미래를 알고 싶으신 분은 얼른 가서 세이지와 운명 상담을 하세요! 어서 가세요!"
rows["488:751402040"]="우리는 아제로스에 대한 원자장애 보고를 듣고 있습니다. 우리의 소식통은 현상이 완전히 자연스럽지 않다고 나타냅니다. 하지만 우리는 그 원인을 정확히 파악할 수 없었습니다. 우리는 몇 가지 이론을 가지고 있지만, 구체적인 것은 없습니다.$B$B당신이 돌아다니면서 의심스러운 요소 활동에 주의를 기울이고, 가치가 있는 것을 발견하면, 지구 반지 발신자에게 알려주세요.$B$B눈을 뜨지 마, 문제가 커지고 있어"
rows["488:8700417"]="그 사람한테는 호드 오크가 강세를 키우고 있는 것 같아서 포털을 통과한 것처럼$b$b<볼진은 3개의 손가락으로 흉터를 넘어서고 있다>$b$b난 전투에서 지옥의 잔소리를 따라 싸우고 있지만, 그를 지휘하게 해$b$b그는 절대로 가족을 넘지 않는다는 걸 배우게 될 거야"
rows["489:205308810"]="크리스탈 포커스? 물론 설명할 수 있어요. 왜냐하면, 당신은 그것을 알아낼 수 있는 뇌의 절반밖에 없거든요.$B$B고전화 된 결정 중추는 간단한 과정으로 열 개의 절도 조각과 결합될 수 있으며, 이것은 충전 된 결정 중추를 생성합니다. 이 충전 된 광선은 치료 특성을 가지고 있지만, 더 중요한 것은 귀신으로 인해 사용하는 것입니다.$B$B보시다시피, 화력 집중력은 귀신에게 특별한 힘을 발휘할 수 있도록 사용될 수 있습니다. 만약 당신이 암흑자리를 가지고 있다면, 가크는 그것에 대해 이야기 할 것입니다."
rows["489:744019643"]="시각적 보조 대상이 되는 것 2$B$B이 변수의 두 번째 결과 변수는 표준 지하 행렬과 비교할 때 많은 원하는 요소를 유지합니다. 이 변수의 일반적인 명칭은 \"왜성\"입니다.$B$B이 변종은 강도를 유지하고 체력 지구에 속하는 것입니다. 어떤 경우에는, 왜기는 심지어 지구의 매트릭스의 인지 능력을 초월합니다. 아제로스다양한 돌 핵 화합물입니다."
