rows["48:992104940"]="정신 통제 의식에 준비됐어"
rows["490:1839831993"]="이 평야를 지나다니면서 많은 계절을 보냈고, 큰 짐승을 사냥했고,$B$B오래전, 거대한 늑대는 타우렌의 동맹이었고, 불타는 군단에 맞서 용감하게 싸웠지만, 그는 악마에 의해 야만적으로 부상을 당했고, 그의 육체의 찢어지는 부분이 치유되지 않았습니다.$B$B이제 그는 고통 속에서 평야를 돌아다니며 고통의 종말을 찾고 있습니다."
rows["490:1971852153"]="난 죄수이야!$B$B날과 제 아름다운 젤펠린을 하늘에서 떨어뜨렸어 호드이건 새로운 건 아니잖아$B$B해적들을 폭격하기 위해 날 해프로 주위를 돌게 하고 난 그녀를 이렇게 유지할 수 있는 부품을 갖고 있지$B$B만약 당신이 그들을 도울 수 있도록 결심한다면, 그녀는 $3078w도 채 안 되는 시간 안에 항구에 도착할 것입니다.$B$B내가 말해주는 범죄야!"
rows["491:1034790830"]="우리는 바로프가 그들의 재산을 보존하고 땅을 차지하기 위해 그들의 수명을 훨씬 더 오래 지난 후에$B$B에바가 떨고 있습니다$B$B이 협정에서 네크로맨스 학교가 탄생했습니다. 저주받은 사람들의 숭배가 탄생한 장소가 그들의 수도가 될 것입니다.$B$B매주 바로프 집이 점점 더 쇠퇴해...$B$B어두운 존재들이 집의 여러 날개에 거주하기 시작했고, 유지보수가 불가능해졌고,"
rows["491:1210835718"]="내가 직접 보고 있을 때까지 트롤을 믿지 않았어 악마의 부패가 없는 오크, 이 불멸한 행성에서 자리를 잡은 자랑스럽고 명예로운 전사$B$B저는 트롤과 호드에게 자신을 증명할 것을 간절히 바랍니다. 제 아버지는 당신이 리치 왕라고 부르는 이 죽은 위협을 다루지 않았습니다. 하지만 모든 설명에 따르면 그는 호드에 대한 끔찍한 위협을 나타냅니다.$B$B난 트롤에게 그의 최고의 전사들을 이끌도록 부탁할거야 노스렌드 그리고 리치 왕하지만 이 전염병은 선례가 필요합니다."
rows["491:1353660501"]="모두 죽었어$B$B어드크블러드는 우리를 뚫고 지나가면서 내가 이해할 수 없는 무언가가 나를 붙잡았어. 말해줘, 네가 그토록 큰 분노를 느꼈어?$B$B<사우르팡의 눈은 잠시 동안 붉은빛을 띠고 있습니다.>$B$B내가 마지막 생존자였어 30 그 비전을 제외하고는 아무것도 기억하지 못해"
rows["492:1927427056"]="슬픈 이야기, 그 이야기도 좀 당황스럽네요$b$b내 사람들은 맥주 맛을 좋아하고 난 예외가 아니네$b$b그래서 내가 구 부드한테 달려갔는데, 그가 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 모든 잔을 내로 내로 내로 내로 갈 수 있는 움직임을 후회하게 되었다$b$b어느 날 밤, 코도도를 떨어뜨릴 만큼의 녹음도 마셨는데, 저는 부드'의 밴드 오'나피트'를  ⁇ 아마에 따라 유혹받았습니다.$b$b내 기억이 나지 않는 마지막은 그  ⁇  안에 갇혀있기 때문이에요"
rows["493:605747427"]="좋아, 거래가 거래가 될거야$b$b우리는 모두  ⁇ 알만으로 들어가서 둘러봤던 밤이었습니다.$b$b나무를 지나가는 바람처럼 울리는 소리를 들릴 때까지는 조용한 곳이었죠. 우리가 알아차리기 전에, 우리는 야만과 애완동물들이 우리 주변에 있을 겁니다. 다음 날, 저는 여기 올라가서,$b$b하루가 지날수록, 죄수들이 죽어가고 있습니다.$b$b이 곳만 알고 있고 더 이상 알고 싶지 않아!"
rows["494:1615228528"]="Vol'jin의 냄새가 나고, 그의 뜨거운 숨결이 네 코에  ⁇ 어 있습니다.$b$b오, 당신은 Anudda 계획? 나도 Anudda 계획을 가지고있다. 내가 당신이 스스로 포위 할 오그리마 . 얼마나 멀리 가는지 볼 수 있습니다. '이 시가 '죽체로 가득 한 후에' 그림자 사냥꾼들이 와서, 우리는 남은 것을 닦아 Kor'kron an ' 얼라이언스 같은 죽여. 당신에게 죽은 ta Sylvanas. Hmm! 나는 계획없이 많은 Darkspear의 생명을 구합니다!$B$B좋아하지 않니, 그럼 첫 계획대로 같이 일해$b$b우린 서로 좋아하지 않는 것조차 없어요"
rows["494:2111130310"]="자연의 모든 것들은 상호 연결된 네트워크에 존재합니다. 생태학입니다. 우리가 그것을 방해하지 않고 관찰하는 것에 주의한다면, 우리 주변의 다양한 생물들 사이의 복잡한 관계를 잘 파악할 수 있을 것입니다.$B$B우리가 그 이해를 한 후에는 모든 생물의 복지를 보장하기 위해 적절한 조치를 취할 수 있습니다. 그 지식이 없으면 개입하면 우리는 확실히 파괴를 일으킬 것입니다.$B$B저는 스포링과  ⁇ 밭주 사이의 복잡한 상호작용을 관찰하기 위해 왔습니다."
rows["494:417970603"]="누가 알겠어, 그게 내가 마지막으로 본 거야$B$B여기서 주제를 벗어나지 않으려고요. 왜냐하면, 제가 이 지휘관에게 맡은 일은 중요하다고 확신하지만, 아이언포지 군대가 아직까지 귀가  ⁇ 어있지 않아야, 우리가 왕국을 지키기엔 너무 무력해"
rows["494:662006589"]="빛의 또 다른 측면일 뿐인 샤머니즘의 길을 가르쳐주었습니다. 바람에 합류하는 것은 오아시스의 물, 내 캠프의 불, 그리고 내가 앉아 있던 땅이었습니다. 모두 말이 있었습니다.$B$B몇 년 동안 그들은 저에게 세상의 요소들과 하나가 되는 것을 가르쳐 주었습니다. 그리고 그들은 제게 하늘의 모든 별들의 세계들, 심지어 이 별들조차도, 이 요소들로 이루어져 있다고 말했습니다.$B$B하지만 나 는 떠나기 위해 충분히 배운 것 이라고 생각 할 때 어느 날 이었습니다."
rows["494:961863890"]="크리스탈 포커스? 물론 설명할 수 있어요. 왜냐하면, 당신은 그것을 알아낼 수 있는 뇌의 절반밖에 없거든요.$B$B고전화 된 결정 중추는 간단한 과정으로 열 개의 절도 조각과 결합될 수 있으며, 이것은 충전 된 결정 중추를 생성합니다. 이 충전 된 광선은 치료 특성을 가지고 있지만, 더 중요한 것은 귀신으로 인해 사용하는 것입니다.$B$B보시다시피, 충전된 초점이 집착된 악마가 특별한 힘을 발휘할 수 있도록 사용될 수 있습니다."
rows["495:1248240420"]="셰쉬, 제발 부탁해 마셔$B$B그래서, 회사 전체가 이 미술품에 대해 거대한 방에서 싸우고 있습니다. 그리고 그 안에 어떻게 반향되는지 아세요! 결국에는 세 조각으로 분해되었고 우리는 개자리를 던졌고,$B$B나머지 부분은 좀 흐릿합니다. 왜냐하면 그 무렵에 구발탈라크의 영이 입구를 만들고"
rows["495:1855141353"]="이 염색체는 창조자들이 세계를 심는 데 사용하는 합성 매트릭스 중 하나입니다. 각 합성 매트릭스는 창조자의 목표를 달성하기 위해 사용됩니다. 아제로스에 대해, 지저계 존재 매트릭스는 이 변형의 결과로 깊은 지역 모양을 위한 친화성을 가진 더 높은 내구성을 가진 존재를 만들기 위해 수정되었습니다.$B$B지구인들은 창조자들에게 서비스를 제공한 후, 예상치 못한 변칙이 발견되었고, 고 스트레스 환경으로 인해 그들의 합성 매트릭스에 영향을 미쳤다."
rows["495:564765494"]="쉐이디 레스트 인에 대한 알려진 바는 거의 없습니다. 제임스 하이얼의 아내와 아이가 탈출하지 못했을 뿐이죠.$b$b제임스도 끌어내려냈지만 그 이후로 그는 변하지 않았습니다.$b$b우리는 많은 흔적을 가지고 있지만 증거는 많지 않습니다. 우리는 경비원들의 노력과 테라모어 주민들의 경호적인 도움으로 이 끔찍한 범죄를 풀 수 있기를 바랍니다.$b$b조사에 도움을 주고 싶다면 불모의 땅 국경에서 숙소의 잔해를 찾을 수 있습니다."
rows["496:1166046431"]="아버지를 기쁘게 해 드리고 싶었던 발스탄은 소규모 병력을 데리고 가 마파람 마을을 사수하게 해 달라고 판드랄에게 부탁했습니다. 당시의 전황으로 볼 때는 당연히 그의 사랑하는 아들에게 잘못된 일이 생길 가능성은 전혀 없었지요. 그러나 미처 함정을 알아채지 못해, 발스탄은 매복해 있던 퀴라지에게 포로가 되었으며 마파람 마을은 흔적도 없이 사라져 버렸습니다. 라작스는 포로가 된 발스탄을 스태그헬름과 나이트 엘프 군대가 있는 최전선으로 끌고 갔습니다. 그리고 그들이 지켜보는 앞에서 이 젊은 나이트 엘프를 잔인하게 처형했습니다."
rows["496:2010442273"]="마라우돈 내 에 숨어 있는 독물 이 내 마음 에 침투 할 때, 현실 에 대한 제 집착 이 점점 떨어지기 시작 했습니다. 그 독물 이 악 을 위해 사용될 것 이라고 염려 한 제 드라이드 자매 들 은 비밀리에 제 왕자 줄 을 빼앗아 두 부분 으로 쪼개고 동굴 에 숨기게 되었습니다.$B$B곧 그 들 은 광기의 희생자 로 གྱུར་자, 그 두 부분 의 왕자 기둥 은 보호 를 받지 않은 채 남았으며, 비레톤게 자신 의 소유 에 들어갔다. 시타이르는 악성 원자인 노크시온 에게 한 부분 을 맡겼고, 그 한 부분 은 오늘날 까지 그 에게 있다."
rows["496:2091558331"]="난 죄수이야!$B$B날과 제 아름다운 젤펠린을 하늘에서 떨어뜨렸어 호드이건 새로운 건 아니잖아$B$B해적들을 폭격하기 위해 날 해프로 주위를 돌게 하고 난 그녀를 이렇게 유지할 수 있는 부품을 갖고 있지$B$B난 당신에게 무슨 일이 일어났는지 책임지지 않을거야 하지만 그녀가 떠나기 전에 배에 올라갈 수도 있어$B$B내가 말해주는 범죄야!"
rows["496:258090506"]="이 질문에 제대로 답하기 전에 지구에 대한 추가적인 배경 정보는 제공되어야 합니다.$B$B처리$B$B지구인의 이상들을 이해하기 위해서는 먼저 지구인이 그들의 설계 의도에 어떤 것을 나타내는지를 이해하는 것이 중요하다. 지구인은 표준 지하 생물 매트릭스의 생존 패러다임을 개선하려는 창조자들의 시도를 나타냅니다. 이것은 상기 매트릭스에 세계와 내재된 구조의 탄력적인 기초를 통합함으로써 이루어졌습니다."
rows["496:628774241"]="오, 호레이 - 당신은 악의 트롤을 죽였어 바로 시간 내에 나를 무기력하게 학살되고 나의 무고한 작은 영혼을 노예로 삼고 그들의 사악한 계획에 힘을 더하기 위해 사용되었습니다 아제로스 그리고 당신이 어떻게 당신의 생명을 위험에 빠뜨렸는지 보고 나를 죽음으로부터 해방시켜야 한다는 것을 보며, 당신은 누구든 어디서 왔든$b$b애슐리는 깊은 숨을 쉬고$b$b당신이 감자 좋아하시길 바랍니다."
rows["496:934034742"]="요원 야-6와 저는 울트리스에서 빈 생물의 침습의 모든 징후를 없애기 위해 보호구역 지휘에서 높은 우선 순위를 받은 임무였습니다. 이것은 전술적 공격이었습니다. 보호구역 감시소에 돌아 가기 전에 우리의 마지막 타격은 그 지역의 육아에서 살을 찌는 아크콘스라는 빈 군주였습니다.$B$B불행히도, 우리는 조금 늦게 도착했습니다. 야-6와 나는 육신 짐승들과의 불투쟁에서 분리되었습니다. 이제 그는 안에 갇혀 있습니다. 적의 선 뒤에 갇혀 있습니다.\010"
rows["497:1062141291"]="네, 젊은여, 이런 것에 대해 설득할 필요는 없어, 워시프와 나는 많은 역사를 가지고 있지만, 당신의 헌신은 주목된다.$B$B제가 말씀드렸듯이 랜드는 그의 사람들에게 새로운 집을 찾았고, 저는 그 사람들을 따를 수 있는 사람들 중 하나였습니다.$B$B한 전쟁에서 다른 전쟁도 생겨났고, 수많은 전쟁들이 일어났습니다. 블랙록 스파이어와 블랙록 족속의 전투에서 두 아들 모두 죽었습니다."
rows["497:174898598"]="라저펜 다운스는 라저펜 크라우스와 같은 포도나무에서 만들어져 있는 전통적인 퀴블보르 종족의 수도이다. 거느러미로 가득한 이 퀴블보르 랩리린트는 충성스러운 퀴블보르 군과 그들의 대사인 죽음의 머리 부족을 소장하고 있다. 그러나 최근에는 무생한 덩굴 위에 임박하는 그림자가 떨어졌다. 퀴블보르 종족을 통제하는 무생의 요원들은 스컬지 - 쿨브링거인 암네르가 주도하는 - 퀴블보르 랩리인트를 장악하고 퀴블보르의 진막을 무생의 요새로 바꾼다. \010"
rows["497:1856095951"]="바로스 클라우드스트라이더와 그의 반지 보호자들은 두 번째 반지를 보호합니다. 당신의 드레크는 반지 보호자들에게 더 많은 일치하지만 바로스는 오클루스의 에너지로부터 만들어진 непроницаемых 방패 뒤에 있습니다.\010붉은 비행기에서 드레이크를 불러낼 수 있는 힘을 줄 수 있어."
rows["497:188184441"]="그래, 맞아요$B$B그래서, 여기 우리는 블랙록 스파이어의 상부까지 침투하고 있습니다. 그들의 주인과 지도자에 대항해요. 이것은 드라키사태 전이었죠.$B$B놀랍게도 모든 것이 계획대로 진행됐고, 우리가 발탈라크의  ⁇ 한 손가락에서 마법서를 꺼내던 지점까지 이르렀습니다.$B$B계속해야 돼?"
rows["497:371050826"]="두 사람이 같은 편에 싸우고 있다는 걸 보여주려면 방법을 찾아야 합니다.$B$B티머머무 포브롤그에 대한 공격은 동맹국으로서 그들을 얻는 기회를 크게 방해할 것이라는 것을 기억해야 합니다.$B$B시작하기에 좋은 곳은 펠우드의 많은 지역에서 발견되는 데드우드 포르볼그입니다. 이 포르볼그들은 템버마우 부족의 적이며, 그들을 죽이는 것은 템버마우족과의 지위를 크게 향상시킬 것입니다."
rows["497:669147180"]="저리 나는 톱니바닥에 떨어지고 있었고, 손잡고 다투고 있었는데, 날카로운 칼만 가지고 있었습니다. 지능 날 구하기 위해서$B$B갑자기 날 날 날 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로 날개로$B$B그리고 그들의 콧수염이 트로피로 남아있지만, 난 그 고통에서 감염된 지경을 받았어요."
rows["498:1469061833"]="당신은 Cenarius의 아들, Remulos와 Zaetar에게 물어.$B$B제 아버지 레무루스는 강하고 아름답고 제 삼촌인 자에타르는 매우 현명한 사람이었고, 거의 전혀 지형이 없었습니다.$B$B나랑 여동생들이 태어난 후, 질투로 맹인화된 자에타르는 동생을 능가하려고 노력했습니다. 그는 자신의 결말을 창조한 사람이었습니다."
rows["498:1703742615"]="드디어 이 감옥에서 나를 해방시킬 사람이 있어!$b$b하드레크 대검장이 우리를 보내서 요새에 대한 정보를 수집해$b$b하지만 늙은 마법사는 많은 트릭을 가지고 있어 마법의 요원이 우리를 발견했고,$b$b하드렉으로 돌아가서 조차 회고해야 하지만 먼저 너한테 궁전 문의 잠금을 뽑아줄게"
rows["498:799473294"]="항상 나를 노인 피트라고 부르지 않았어$B$B한 번, 내가 젊고 난생이었을 때, 나는 내  ⁇ 을 스타일로 벨리라는 달콤한 부스럼 소녀를 인상적이라고 생각했습니다.$B$B ⁇ 리, 그녀는 다른 것 같았어요. 딱딱한 것 같았어요. 그쪽은 큰 것 같았어요.$B$B그래서 저는 그녀의 피부처럼 흰 석회암 조각을 발견하고, 조각을 하고, 예술작품이라고 부르는 것을 만들려고 했습니다. 하지만 저는 엄청난 규모를 잘못  ⁇ 게 되었습니다."
rows["498:874493421"]="필사자 여러분, 이 곳을 포위하는 끔찍한 부패로부터 저를 해방시켜주셔서 감사합니다. 아직 완전히 회복되지 않았지만,\010내가 너와 너의 친구들에게 얼음의 강도를 부여하여 너의 피해를 증가시키고 적의 공격으로 인한 피해를 줄일 수 있다. 만일 너희 중 한 명이 전투에서 쓰러질 경우, 나는 너를 얼음 블록에 얼어붙여, 모든 피해로부터 잠시 보호할 수 있다. 이 능력은 내 힘을 세금을 부과하고, 나는 그것을 사용한 후에 쉬어야 한다."
rows["499:1218920877"]="전 전에 말했듯이 키리스는 계획을 가지고 있었다$B$B모든 종들은 약점을 가지고 있습니다. 그들이 붕괴 상태에 도달할 때까지 그들의 신체적 형태를 그들의 돌 근처에서 처벌하십시오. 그 때만, 그리고 그 시점에서만, 묶음 돌은 공격에 취약합니다. 당신은 돌을 파괴하는 데 서둘러야합니다. 그러나 노예가 회복되면 그들은 다시 해를 끼칠 수 없습니다."
rows["499:1550029764"]="보들리는 의심의 여지없이 당신을 쳐다보지만 계속...$B$B여기 우리는 마법 책, 그리고 Kormok, 우리의 두머리 오그르 강령술사, 네 눈을 모두 이상한 모습으로 볼 수 있습니다. 그것은 정말 무서운 일이었습니다. 왜냐하면 그 두 번째 눈은 항상 죽은 것처럼 보였기 때문입니다.$B$B나머지 사람들은 미쳤고, 우리 중 일부는 그냥 떠나라고 말했고, 다른 사람들도 자기들만을 위해 원했습니다."
rows["499:2003887595"]="이 물질은 인종 합성에서 사용되는 기본 물질입니다. 아제로스의 껍질의 교차 부분은 창조자들이 사용하는 전형적인 바이오매스 건설 기초가 아닌 지구 합성의 기초로 사용되었습니다.$B$B세계 구성에 대한 연구로 인해 창조자들은 이 세계의 본질의 회복탄력성을 상징하는 증강된 존재가 합성될 수 있다는 이론을 제시했습니다. 이것은 아제로스의 다양한 석기 핵 화합물을 혼합하여 기초로 사용함으로써 달성되었습니다."
rows["499:229542766"]="법의 반지의 너머에 있는 미묘한 어둠의 불을 발견해 내라$B$B아이언펠을 타우리산 신성당으로 데려가서 제 명예로 세워진 동상의 손에  ⁇ 을 두라$B$B이 일이 끝나면, 내가 주 열쇠를 보관한 방이 열릴 것이고, 더 중요한 것은, 아이언펠은 영원히 내 손에 남아 있을 것입니다. 그들이 해마를 제거하려고 시도한다면,\010"
