rows["500:152715349"]="<비울이 조부모님 얼굴에 흐르고 있습니다.>$B$B난... 난... 두루탄이 아이를 낳을 수 있게 살아남았어... 드라카가 떠나기 전에 내게 말한 아이는... 이 세상에서 아이를 키우는 것이 그들의 가장 큰 두려움이었다. 그 문의 다른 쪽에는 그들의 유일한 희망이었다. 난 두루탄에게 말하지 않을 용기를 가지 않았지만, 비밀리에, 나는 영들을 그들을 지켜달라고 간청했습니다. 그들의 아이를 보호하고 그들에게 힘을 주도록.$B$B난 손자를 만나야 돼, 내가 너무 약해\010"
rows["500:2000639610"]="매혹적인 것... 오크들이 인간의 냄새가 불쾌하다고 주장하는 것을 들었는데, 그리고 사람들이 오크들의 냄새가 불쌍하다고 주장하는 것을 들었는데,$B$B내 주장의 타당성에 의문을 품고 있습니까?$B$B내가 집을 떠나게 된 것은 탐욕이었으니 탐욕이 나를 다시 데려가리라"
rows["500:230553133"]="아예, 소식이 빠르게 퍼져나갔고 곧 모든 Menethil 그것을 볼 수 있도록 모였습니다 bettin '과 과일을 판매하는 등, '에' 큰 리가마롤로로 철조해야 하는 규칙에 대한 약간의 불안이 있었다, ' 시장 스스로 동의까지 '비청' 피는 아무것도 셀 수 없다.$B$B그래서  ⁇ 크는 무릎을 꿇고 그녀는 의자에 올라서서 그 큰 뚱뚱한 다리로 뒤돌아갔고..."
rows["500:67202796"]="오래전 악마의 신자 킬제덴은 네르즈울의 샤만에게 seemingly 끝없는 고문을 당했습니다. 뒤틀린 황천, 우리가 얼어붙은 왕좌라고 부르는$b$b아타스는 얼음모른으로 크리스탈을 깨고 네르즈울의 영혼과 합병하여 리치 왕이 되었다. 이 왕좌의 분쇄는 현재 성곽에 흩어져있는 [상빙]의 얼은 조각들을 만들었습니다."
rows["501:1206940425"]="악당은 정말 악당한 존재입니다. 불지옥처럼 물리적으로 강하지는 않지만, 지혜로운 마녀는 잔인한 힘이 항상 답이 아니라는 것을 알고 있습니다.$B$B펠하우드는 마나 적들을 물리치기 위해 그 힘과 속력을 사용하며$B$B지옥에 대한 더 많은 것을 알고 싶다면 저 반대편의 마가즈와 이야기해봐"
rows["501:1326948288"]="피부 작업 은 피부, 피부, 껍질 등 으로 갑옷, 담옷, 장갑 강화 킷 및 기타 유사한 아이템 을 제작 할 수 있습니다. 피부 작업 에 필요한 다른 재료 는 무역 및 피부 작업 업체 에서 구입 할 수 있습니다.\010스킨링은 스킨링과 잘 어울리는데, 이는 자신의 원료를 수집할 수 있게 해준다. 스킨링은 다른 필수품, 예를 들어 ത്രെ드와 염료를 무역이나 스킨링 업체에서 구입할 수 있다.\010고도로 숙련된 가죽 작업자들은 또한 팔찌와 다리 장갑을 강화할 수 있습니다."
rows["501:1443948142"]="지구의 합성 매트릭스가 불안정해지면 두 가지 결과가 있습니다. 시각적 보조 표현 1번을 시작합니다.$B$B첫 번째 변종 매트릭스는 합성의 퇴행성 산물이며, 여기서 \"Trogg\"의 공통 명칭으로 지정된다. 이 변종은 강도를 유지하고 체력 지구인들과 비교할 수 있지만 인지 처리 능력이 거의 완전히 손상되었습니다. 의지의 힘과 강한 속임수 감각은"
rows["501:1543136588"]="고대 전쟁 때 반신 아가마가건은 불타는 군단과 싸우기 위해 등장했다. 거대한 돼지는 패배했고, 시간이 지남에 따라 그의 피가 떨어지는 지역에서 거대한 사뭇가지를 달린 포도나무가 생으로 자랐습니다. 퀴블보르는 이 지역을 점령하고 신성한 곳으로 삼았다. 이 거대한 사뭇가지를 식민지의 중심은 라저펜이다. 라저펜 크라우르는 크론, 샤르lga 라저플랑에 의해 정복되었다. 어떤 추측에 따르면 그는 어떤 기묘한 목적으로 스컬지의 에이전트들과 협상하고 있었다.\010"
rows["501:1884275785"]=" ⁇  모로그에 위치한 곤메리건은 여러 세대에 걸쳐 지미들의 수도였지만 최근에는 돌연변이 트로그가 침투했다. 기술공 메카토르크는 도시의 방사성 폐기물 탱크를 긴급하게 공기를 할 것을 명령했다. 트로그가 방사선화되었지만, 포위기는 계속되었고, 기둥들은 마른 도시인 아이언포지, 고위 기술공 이제 용감한 영혼들을 모집해 사랑받는 도시를 되찾도록 도와줍니다. \010"
rows["502:1650383136"]="Fel 에너지는 또한 우리가 빛그 당시 저는 정확히 이유를 몰랐지만, 변명자로서 그것을 찾아내기로 했습니다. 그래서 순례하러 갔습니다.$B$B전쟁 이 운명적 으로 끝 을 맺은 후, 저는 분해 된 행성 의 사막 으로 여행 하여 우리 에게 돌아 오라고 빛 를 간청 하였습니다. 하지만 수십 년 이 지나갔지만, 빛 은 결코 제 기도 에 응답 하지 않았습니다.$B$B더 많이 듣고 싶은 게 이것인가요?"
rows["502:1674545091"]="제가 처음 샤트라트에서 제  ⁇ 족 아카데미를 설립했을 때, 그 곳은 그리 많이 사람이 없었어요. 그 다음 난민들이 몰려들기 시작했고 나라우들은 그들을 수용하기 위해 모든 건물을 필요로 했습니다.$B$B아카데미는 아직 닫혀있지만, 영구적이지 않아서 새로운 장소를 찾아볼게요$B$B그러면 새로운 세대의 악당들은 '구그'n 미스'와 같은 기본 요소를 배우게 될 것이고, 강탈을 물리치고, 다른 사람을 다형성 물질을 깨뜨리는 것에 대해 비난할 것입니다. 그리고 악당의 핵심 규칙을 잊을 수 있는 사람들은 진짜 악당들은 가짜를 하지 않습니다."
rows["502:305385174"]="심장의 힘은 행동의 결단력을 부여합니다. 순수하고 솔직한 의도에 뿌리를 둔 행동입니다. 균형을 유지하는 것은 자만하거나 비단적인 것이 아닙니다.$B$B당신 은 믿 을 수 있는 것 을 위해 결단 을 나타내야 하며, 그 를 위해 싸워야 합니다. 곰 어머니 는 새끼 를 보호 하는 데는 끝없는 확신 을 나타냅니다. 고장 한 곰 이 자신의 굴 을 보호 하는 것 처럼요. 이 결단 과 이심 이 바로 그 강도 입니다."
rows["502:771181819"]="저는 제 백성 에게 돌아왔고, 대부분 브로크네에서 온 사람 들 이 웃는 얼굴 과 팔 을 뻗어 뻗어 있는 모습 으로 환영 을 받았습니다. 제 부재 에서도 많은 드레네이 들 이 우리 에게 대한 편견 을 계속 해 왔습니다. 하지만, 마치 그들이 제가 올 것 을 알고 있는 것 처럼요. 그리고 그 이유 를 곧 알게 되었습니다.$B$B델렌, 모든 드레네이의 예언자이자 지도자, 그의 비전 중 한 곳에서 나의 귀환을 보았고, 저 또한 환영하러 갔습니다. 그는 나와 사설적으로 이야기하기를 요청했습니다. 그리고 제가 그에게 나의 이야기를 이야기 할 때, 그는 이 또한 그가 예상했기 때문에, 머리를 숙이고 웃었습니다."
rows["503:1828343620"]="우리는 이전처럼 통합되어 있습니다. 칼림도어, 봉쇄의 종말과 대해 양쪽에도 많은 피를 흘린 총체적인 전쟁의 종말$b$b이제 평화의 일으로 돌아가서 테라모어 근처에 군대를 배치하고, 길니안족들의 땅을 깨끗하게 해내고,$b$b이제부터, 얼라이언스는 적극적으로 움직일 것입니다. 다시는 Hellscream 같은 사람이 없을 수 있습니다."
rows["503:2004289290"]="수백 년 전, 위대한 도시 타우리산은 현재 폐허가 된 불타는 스텝으로 알려진 풍성한 땅 위에 자랑스럽게 서 있었다.$B$B타우리산은 암흑 철 Dwarves의 고향이었고 그 당시에는 Dwarf Nation의 내전 중이었습니다.$B$B이 지역 은 한때 붉은마루 산맥 의 일부분 이었습니다. 그 날 까지는 타우리산 은 거대한 폭발 으로 삼켜졌다. 도시 는 황폐화 되어 그 주변 지역 은 먼지 텅 비어 버렸다.\010"
rows["503:298415357"]="오시딘도온의 영이 축복받은 사람들은 영 조각의 형태로 강력한 영혼을 사로잡을 수 있다고 합니다. \010내가 알아낸 유일한 것은 그들이 오치윈의 깊은 곳에서 온 것 같다는 것입니다. 만약 여러분이 이런 영 조각들을 만나게 된다면"
rows["503:651135939"]="저는 오아시스 를 발견 한 것 이 행운이었으며, 그 에 대한 답변 을 받기 전 까지 머물기로 결심 했습니다. 그래서 저는 거기 앉아, 꼭 필요 한 때만 움직이고, 수영장 근처 에 다가올 생물 들 을 먹고 살았습니다.$B$B제가 말했듯이, 수십 년 동안 아무런 대답도 없이 흘렀습니다. 하지만 저는 어느 저녁에 특히 아름다운 해가 서는 것을 기억합니다. 따뜻한 지파리는 땅 전체에 날아갔고, 저는 목소리가 들렸다고 확신했지만, 아무도 없었습니다.$B$B상상할 수 있듯이, 마침내 정신이 나갔다고 생각했어요."
rows["504:1355982499"]="난 몰라, 하지만 그들이 그랬다는 걸 기쁘다. 이 휴식 기간은 안코르이트 엘바돈이 내 지휘 아래의 많은 남녀를 구해줬다. 나는 내 가장 유난한 스카우트를 몇 명을 보내왔고, 그들은 흥미로운 것을 보고했습니다. 거의 모든 선블레이드 보호자들은 전원을 꺼버렸습니다. 킬제덴의 세력은 에너지를 절약하고 있고, 단지 하나의 활동적인 보호자를 가지고 우리를 포함시키는 것으로 만족하고 있습니다."
rows["504:1492074055"]="화염  ⁇ 스 (Ragefire Chasm) 는 오크들의 새로운 수도 도시 오그리마 아래의 화산 동굴의 네트워크를 구성한다. 최근에는 악마적인 그림자 협의회에 충성하는 종파가 샤스마의 불 깊은 곳에서 거주하고 있다고 소문이 퍼져 나갔다. Burning Blade라는 이름으로 알려진 이 종파는 듀로타의 주권을 위협한다. 많은 사람들이 오크 Warchief Thrall가 블레이드의 존재를 알고 있으며, 그 구성원들이 그를 직접 그림자 협의회로 이끌 수 있을 것이라는 희망으로 그것을 파괴하지 않기로 선택했다고 믿는다. \010"
rows["504:1741424508"]="크로시크를 숭배하는 사우로크들은 두려워하기 때문에 그렇게 합니다.$b$b우리 는 모두 가행 하는 작은 악마 사우르들 뿐이라고 하고, 하늘 에서 살고 있는 보이지 않는 전능 한 악마 사우르의 호의를 얻기 위해 우리의 \"힘\"을 증명하고 있다고 합니다.$b$b실로 그들은 그렇게 믿노라$b$b우린 악마사선이 아니라 사루크입니다. 그리고 우리가 죽으면 영원한 사냥도 없고 약속된 천국도 없고 약한 사람에게 대한 처벌도 없고, 크로스도 없습니다. 우리는 먹혀지고 우리의 유골은 쓰레기 덩어리에 던져질 것입니다."
rows["504:594155746"]="땅 을 연구 하면서 땅 아래 깊이 에 뻗어 있는 동굴 을 발견 하였습니다. 이 수로 들 은 땅 위 가 건조 한 사바나 아래 에서 수 킬로미터 가량 떨어진 곳 에서 지하 로 흐르는 강 들 을 운반 하였습니다. 그 들 은 바람 과 증기 가 그 깊은 곳 을 흐르면서 만들어 낸 울음 으로서 울음 으로 부르는 동굴 이라고 이름 을 붙였습니다.$B$B이 물은 이미 표면에  ⁇ 어 올라왔고 작은 풍성한 오아이스처럼 불모의 땅..."
rows["504:784701712"]="천 년 전 아탈라이라는 트롤 사제들이 고대 혈액 신인 하카르 영혼살상자 (Hakar the Soulflayer) 를 다시 데려오려고 시도했다. 그 결과 내전 이후 사제들은 패배하고 슬픔의 습지로 추방되었다. 그곳에서 그들은 하카르에게 성전을 세우고 물리 세계에 도착할 준비를 했다. 용어 애스펙트 이세라는 곧 아탈라이의 계획을 알게 되었고, 무더지의 아래에서 성전을 파괴했습니다. 오늘날까지, 성전의 유해들은 강력한 녹색 드래곤들에 의해 보호됩니다.\010"
rows["505:1740614242"]="드레네이 돌아왔어요. 이 그룹은 서쪽 도로에서 순찰을 하던 중 두 명의 최고의 늑대 라이더를 쏘아 올렸습니다.$B$B지금 무슨 일이 일어나고 있는지 모르겠지만 내 스카우트들에 따르면 하라에 혈연 엘프와 드레네이들이 있다고 합니다. 저는 혈연 엘프 애호가 아닙니다. 하지만 제가 싫어하는 한 가지 일이라면 드레네이입니다.$B$B하라는 서쪽으로... 지금 가고 싶으면"
rows["505:714320598"]="군중들의 흥분, 싸움의 흥분이 - 당신은 그것을 보아야 했습니다! 그 오그레들이 디어 마우르 경기장을 장악한 이래서 저는 여기 야영을 할 수밖에 없었습니다.\010만약 싸움을 하고 싶다면 스카르는 라리스 파빌리온으로 향하고 있었고, 라즈라는 뉴 타라나어 쪽으로 날아가고 있었습니다."
rows["505:767496107"]="오, 도카는 어디서 시작되는가!?$B$B먼저 농부들은 씨앗을 뿌리고 작물을 채취합니다. 채소를 요리하는데 사용할 수 있고, 시장에서 팔 수 있고, 다른 구매자에게 거래 할 수 있습니다. 그리고 많은 다른 것들이 있습니다.$B$B그 다음에는 하프힐에 있는 모든 사람들이 만나게 되는데, 거기 사는 사람들은 정말 흥미롭습니다. 심지어는 나 같은 원숭이에게도요. 당신은 그들에게 선물을 주고 좋은 친구를 만들죠. 그들은 당신에게도 좋은 선물을 줄 수도 있습니다.$B$B항상 농장에서 할 일이 많아요!"
rows["506:359562510"]="블래스텐하이머 5000 울트라 캐논 은 최첨단 단인 발사 기기 이다. 용의 속도 가까이에서 유용 한 로드를 전달 하는 이 대포 는 항공 및 연연력 으로 세계적으로 유명한 블래스텐하이머 가족 의 자랑 과 기쁨 이다!$B$B만약 당신이 새처럼 자유롭게 날아다니기 위해 하늘을 날아다니고 싶다면, 페어의 동쪽 끝에 있는 맥시마 블래스텐하이머를 찾아라."
rows["506:371850018"]="한때 북부의 보석 로데론아타스 왕자는 그의 멘토인 우더 라이트브링거에 반하여 수백 명의 자신의 주하들을 죽였는데 리치 왕 곧 그 뒤의 도시로 돌아갔고, 스컬지 - 강력한 릭, 케일'투자드, 그리고 스카르렛 십자군 대십자사 다트로한이 지휘하는 함대가 \010"
rows["506:528292243"]="나는 아무 것도 끌어내지 않는다! 그는 그가 원하는 모든 편지를 보낼 수 있다. 나는 그의 '전략적' 계획을 완전히 알고 있으며, 그는 그 여인과 내가 파스트라이더들이 해야 할 일에 전적으로 동의한다는 것을 알고 있습니다. 스카도프라인 트롤들이 처리되면, 그리고 그때만 우리가 우리의 관심을 디테톨메로 돌릴 것입니다. 나는 스컬지가 더 큰 위협이 될 것이라는 것을 알고 있지만, Tranquillien은 그들을 지금 동안 억제해야 할 것이다. 트롤들을 무시하는 것은 자살일 것입니다! 해고, Dusking."
rows["506:700902373"]="제3차 전쟁 당시 다라란 마법사의 미생한 자들에 대한 진전이 부족함에 좌절되어, 아루갈 대장관은 자신의 부위의 줄어가는 순위를 강화하기 위해 외차원 Worgen을 소집하기로 결정했다. 늑대인들은 스컬지를 학살하고, 그 다음 빠르게 마법사에 자신을 돌입하고 귀족인 실버라인 대장님의 요새를 포위했다. 요새는 빠르게 그림자와 폐허로 떨어졌다. 죄책감으로 미쳤고, 아루갈은 Worgen을 자신의 자녀로 채택하고 새로 'Shadowfang Keep'로 철수했다. \010"
rows["507:1881145160"]="SI:7가 나를 발견했을 때, 그들은 저를 집으로 데려가고 싶어했습니다. 저는 도망쳤습니다.$B$B호드호가 날 발견하기까지는 오래 걸리지 않았습니다.$B$B뱀의 심장 전투에서 난 혼란 속에서 빠져나갔고 한 상인이 자기 가족들과 함께 서쪽으로 도망쳐 주의 경비로 갈 수 있게 허락했다.$B$B그 곳에서 메이 버럴보텀을 만났어요.$B$B그녀는 크레인 윙 주문에 대해 이야기했고 그녀의 조언에 따라 저는 청중을 찾아서 성전으로 가자$B$B저는 샤가 도착했을 때 그 학생들과 공부하고 있었습니다."
rows["508:1131401299"]="그는 자신을 기어마스터 메카조드라고 불렀고 우리가 도착했을 때 그는 생존자들을 기계적인 존재로 바꾸는 일에 바빴습니다!$B$B그는 우리를 따뜻하게 환영했고 그는 전설적인 울두르의 홀에서 타이탄을 지키는 \"대 건축가\"라고 부르는 무언가가 만든 최초의 곤충 중 한 사람이었다는 것을 설명했습니다.$B$B그는 수천 년 전에 잘못 작동했던 곳에서 우연히 제 팀이 빨아들인 막상이었죠. 우리는 바로 그 위에 펌프 스테이션을 건설한 것이 행운이었습니다."
rows["509:1563523944"]="최근 나라렉스라는 밤 elf druid가 불모의 땅의 중심에 지하 동굴의 네트워크를 발견했다. 그는 동굴의 샘물을 사용하여 불모의 땅의 풍요로운 상태를 회복할 수 있다고 믿으며, 드루이드는 전설적인 에메랄드 드림의 에너지를 빨아들기 시작했다. 그의 비전은 어떻게든 악몽이 되었지만, 곧 울고 있는 동굴은 악성, 치명적인 맹수들의 동굴로 변했습니다. 나라렉스는 여전히 에메랄드 드림의 가장자리 너머에 갇혀있는 동굴 내부 어딘가에 거주한다고 한다. \013"
rows["509:1615025617"]="하지만, 이 거미들은 우리가 걱정할 필요가 없습니다. 그 여왕인 베티라크가 진짜 위험입니다. 그 거미가 있는 요새는 우리 손이 닿지 않는 동쪽에 있습니다.$b$b그리고 그들은 또한 거대한 거미입니다. 믿거나 말거나, 여기 보이는 12피트 길이의 거미들은 작은 거미들입니다. 말 그대로 라그나로스의 종이 아닐 수도 있지만, 그들은 우리 사안에 대한 위험성이며, 그런 식으로 대접되어야 합니다."
rows["509:1776804706"]="울다만 은 고대 타이탄 웅덩이 이다. 세계 창조 이래 지구 안 에 묻혀 있다. 이 도시의 왜성 발굴 은 최근 타이탄 들 의 첫 번째 실패한 창조물 인 트로그 를 공개 하였다. 전설 은 타이탄 들 이 트로그 실험 을 실패 로 간주 할 때 다시 시도 한 것 이라고 한다. 그 결과 왜성 인종 이 탄생 하였다. 이 비밀 은 전설적인 노르건논 디스크 에 기록 되어 있다. 고대 도시의 바닥 에 있는 거대한 유물, 살아있는 돌의 거대한 건축물 으로 보호 되어 있다. \013"
rows["50:1005248893"]="이 물건은 또 다른 재계급이 필요해요?"
