rows["510:1532137300"]="마라우돈은 사막의 가장 신성한 장소 중 하나입니다. 큰 사원/굴은 반신인 센리우스에게 태어난 두 불멸의 아들 중 한 명인 자에타르의 묘지입니다. 전설은 자에타르와 지구 원자 공주인 테라드라스가 잘못 태어난 켄타우르 인종을 낳았다고 한다. 그들이 등장하자 야만적인 켄타우르는 아버지를 반도하고 죽였다고 한다. 일부 사람들은 테라드라스가 슬픔에 빠진 자에타르의 영을 휘어지는 동굴 안에 갇혔다고 믿고 있습니다. "
rows["512:1876811283"]="스톰윈드 항구에서 좋은 일을 한 후에 이 왜기로부터 좀 느긋하게 될 것 같다고 생각하세요...$B$B난 이 동상을 최대한 빨리 램프에 올려놓고 다시 올려놓고 싶지만, 그녀는 모든 걸로 불평을 하고 있어요. 모든 문제를 해결하기 위한 해결책은 그것을 폭발시키는 것 같아요. 마치 난 괴물이나 괴물과 같이 일하고 있는 것 같지만, 적어도 그들은 맑은 상태일 겁니다.$B$B우리 팀의 일꾼들, 징계도 없고$B$B나쁜 태도, 게으른 팀... 이건 빨리 해결되지 않을 거야."
rows["517:1680319328"]="살라잔의 무신한 종들은 섬의 모든 짐승들을 죽이고 나무와 식물을 불태워버렸습니다. 우리는 섬의 생명을 구해야 했습니다. 하지만 우리는 살라잔의 권력을 구하지 못했기 때문에, 우리는 자연의 모든 영들과 연결되는 새로운 방법을 보여주었습니다. $B$B처음에는 힘들겠지만, 스미럴드 드림에 어떻게 도달하고 영들과 대화하고 직접적으로 그들에게서 배울 수 있는지 보여줘!"
rows["519:1527927192"]="\"달의 브루\" 클럽을 들어본 적 없나? 그 여자애들은 파티를 좋아해요. 그들이 원하는 대로 한다면 브루페스트는 끝나는게 없었을 겁니다.$b$b하지만 이제 그들은 브루페스트 정신을 유지하기 위한 가장 좋은 방법은 사람들이 그들의 클럽에 가입할 수 있게 하는 것이라고 생각했습니다.$b$b작은 수수료로 몇 개의 토큰만 받아 가입할 수 있습니다. 당신은 매달 맥주를 보내며 같은 맥주를 구입할 수 있습니다. 당신이 그것을 좋아한다면. 그것은 최첨단 물건입니다. 그리고 Brewfest의 정신이 결코 사라지지 않도록 하는 방법입니다."
